ExternalServiceRegistration.schema:
{
  "openapi": "3.0.3",
  "info": {
    "title": "SSP Business Partner Integration",
    "version": "2.0.0",
    "contact": {}
  },
  "servers": [
    {
      "url": "https://rb-cpi-central-q.it-cpi018-rt.cfapps.eu10-003.hana.ondemand.com"
    }
  ],
  "paths": {
    "/http/rb.bbm.ssp.mdm.bp.customevent.sf": {
      "post": {
        "operationId": "createBusinessPartner",
        "summary": "Creates Business Partner in Athena",
        "description": "Push Business Partner data from Salesforce to Athena via CPI",
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "accountCreate": {
                    "type": "object",
                    "properties": {
                      "Id": { "type": "string", "description": "Salesforce Account Id" },
                      "CorrelationId": { "type": "string" },
                      "Name": { "type": "string" },
                      "Type": { "type": "string" },
                      "RecordTypeId": { "type": "string" },
                      "BillingStreet": { "type": "string" },
                      "BillingCity": { "type": "string" },
                      "BillingState": { "type": "string" },
                      "BillingPostalCode": { "type": "string" },
                      "BillingCountry": { "type": "string" },
                      "BillingLatitude": { "type": "number" },
                      "BillingLongitude": { "type": "number" },
                      "BillingGeocodeAccuracy": { "type": "string" },
                      "ShippingStreet": { "type": "string" },
                      "ShippingCity": { "type": "string" },
                      "ShippingState": { "type": "string" },
                      "ShippingPostalCode": { "type": "string" },
                      "ShippingCountry": { "type": "string" },
                      "ShippingLatitude": { "type": "number" },
                      "ShippingLongitude": { "type": "number" },
                      "ShippingGeocodeAccuracy": { "type": "string" },
                      "PhotoUrl": { "type": "string" },
                      "CurrencyIsoCode": { "type": "string" },
                      "OwnerId": { "type": "string" },
                      "CreatedDate": { "type": "string", "format": "date-time" },
                      "CreatedById": { "type": "string" },
                      "LastModifiedDate": { "type": "string", "format": "date-time" },
                      "LastModifiedById": { "type": "string" },
                      "txt_AdditionalName__c": { "type": "string" },
                      "pkl_IsTradingPartnerNoRequired__c": { "type": "string" },
                      "pkl_Language__c": { "type": "string" },
                      "txt_TradingParnerNo__c": { "type": "string" },
                      "pkl_CivilianCustomer__c": { "type": "string" },
                      "ftxt_GTS__c": { "type": "string" },
                      "pkm_BoschPartnerRole__c": { "type": "string" },
                      "pkl_Status__c": { "type": "string" }
                    },
                    "required": [
                      "Id",
                      "CorrelationId",
                      "pkm_BoschPartnerRole__c",
                      "Name",
                      "BillingStreet",
                      "BillingCity",
                      "BillingState",
                      "BillingPostalCode",
                      "BillingCountry"
                    ]
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Success message",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "accountCreateResponse": {
                      "type": "object",
                      "properties": {
                        "Status Code": { "type": "string" },
                        "Status Text": { "type": "string" },
                        "BPId": { "type": "string" },
                        "CorrelationId": { "type": "string" }
                      },
                      "required": [
                        "Status Code",
                        "Status Text",
                        "BPId",
                        "CorrelationId"
                      ]
                    }
                  }
                }
              }
            }
          },
          "404": {
            "description": "Not found",
            "content": {
              "text/html": {
                "schema": {
                  "type": "string"
                }
              }
            }
          },
          "500": {
            "description": "Error message",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "accountCreateResponse": {
                      "type": "object",
                      "properties": {
                        "Status Code": { "type": "string" },
                        "Status Text": { "type": "string" },
                        "CorrelationId": { "type": "string" }
                      },
                      "required": [
                        "Status Code",
                        "Status Text",
                        "CorrelationId"
                      ]
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
